package com.giraffeslovebeauty.acmforever;

import android.app.AlertDialog;
import android.content.Intent;
import android.os.Bundle;
import android.view.WindowManager;
import android.widget.*;
import java.util.*;
import org.json.*;

/** Current-page selection binds immutable snapshots; passwords exist only for this operation. */
public final class AdminAccountsActivity extends AdminPageActivity {
    private int page=1;private String query="",school="",status="";private JSONArray results=new JSONArray();private final Map<String,JSONObject> selected=new LinkedHashMap<>();private volatile boolean halt;
    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);if(b!=null){page=b.getInt("page",1);query=b.getString("query","");school=b.getString("school","");status=b.getString("status","");}}
    @Override protected void onAccessLost(){halt=true;results=new JSONArray();selected.clear();AccountExportProvider.clear(this);}
    @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putInt("page",page);b.putString("query",query);b.putString("school",school);b.putString("status",status);}
    @Override protected void onDestroy(){halt=true;results=new JSONArray();selected.clear();AccountExportProvider.clear(this);super.onDestroy();}
    @Override protected void renderAdmin(){if(!access()){results=new JSONArray();selected.clear();AccountExportProvider.clear(this);finish();return;}resetPage("账号管理");selected.clear();if(results.length()>0){showResults();return;}LinearLayout form=card(body);EditText q=input(form,"姓名、用户名、QQ",query),s=input(form,"学校（空为全部）",school),t=input(form,"业务身份（空为全部）",status);form.addView(button("筛选",()->{query=q.getText().toString().trim();school=s.getText().toString().trim();status=t.getText().toString().trim();page=1;renderAdmin();}));form.addView(text("仅维护已开户账号，当前页最多选择20人；批量开户仍在网页。",12));form.addView(button("批量重设普通成员临时密码",()->confirmBatch(null)));if(api.isRoot())form.addView(button("批量修改角色（Root）",()->new ModalDialogs.Builder(this).setTitle("目标角色").setItems(new String[]{"普通成员","管理员","Root"},(d,w)->confirmBatch(new String[]{"member","admin","root"}[w])).setNegativeButton("返回",null).show()));
        LinearLayout slot=card(body);read("/api/admin/web-accounts",slot,true,result->{JSONArray rows=(JSONArray)result;ArrayList<JSONObject> filtered=new ArrayList<>();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(r.isNull("qq_id")||!"active".equals(r.optString("account_state")))continue;String hay=(r.optString("name")+" "+r.optString("real_name")+" "+r.optString("qq_id")).toLowerCase(Locale.ROOT);if(!hay.contains(query.toLowerCase(Locale.ROOT))||!school.isEmpty()&&!school.equals(r.optString("school"))||!status.isEmpty()&&!status.equals(r.optString("status")))continue;filtered.add(r);}int total=filtered.size();page=Math.min(page,Math.max(1,(total+19)/20));slot.addView(text("共 "+total+" 个可维护账号 · 第 "+page+" 页",13));for(int i=(page-1)*20;i<Math.min(page*20,total);i++){JSONObject r=filtered.get(i);LinearLayout b=card(slot);b.addView(text(r.optString("name")+" · "+r.optString("qq_id"),18));b.addView(text("真实姓名："+(r.isNull("real_name")||r.optString("real_name").isEmpty()?"未填写":r.optString("real_name"))+"\n学校："+r.optString("school","未填写")+" · 身份："+r.optString("status")+"\n权限："+r.optString("role")+" · "+(AdminMemberEdits.active(r)?"已启用":"已停用")+"\n最近登录："+TrainingUi.date(r.optLong("last_login_at")),13));CheckBox choose=new CheckBox(this);choose.setText("选择此账号");choose.setOnCheckedChangeListener((v,on)->{if(on)selected.put(r.optString("qq_id"),r);else selected.remove(r.optString("qq_id"));});b.addView(choose);b.addView(button("成员资料与单人操作",()->{opening=true;startActivity(new Intent(this,AdminQuickActivity.class).putExtra("member",r.optString("qq_id")));}));}equalButtons(slot,button("上一页",()->{if(page>1){page--;renderAdmin();}}),button("下一页",()->{if(page*20<total){page++;renderAdmin();}}));});}
    private void confirmBatch(String role){if(selected.isEmpty()){notice.show("批量操作",new IllegalArgumentException("请先选择当前页的账号"));return;}ArrayList<JSONObject> targets=new ArrayList<>(selected.values());for(JSONObject r:targets)if(role==null&&(!"member".equals(r.optString("role"))||!AdminMemberEdits.active(r))){notice.show("批量操作",new IllegalArgumentException("临时密码仅支持已启用普通成员，请重新选择"));return;}new ModalDialogs.Builder(this).setTitle(role==null?"重设 "+targets.size()+" 个临时密码？":"将 "+targets.size()+" 个账号角色设为 "+role+"？").setMessage("使用当前读取的账号快照逐项提交。冲突与结果未知不会自动重试；权限失效会停止后续操作。成功密码仅本次页面可见，离开前请主动导出。旧登录会话会失效。").setNegativeButton("返回",null).setPositiveButton("确认",(d,w)->batch(targets,role)).show();}
    private void batch(List<JSONObject> targets,String role){long owner=api.sessionGeneration();writeRequest(()->{JSONArray items=new JSONArray();for(JSONObject target:targets){if(halt||owner!=api.sessionGeneration()||!api.isAdministrator()||role!=null&&!api.isRoot())break;String qq=target.getString("qq_id");try{api.refreshSession();if(halt||owner!=api.sessionGeneration()||!api.isAdministrator()||role!=null&&!api.isRoot())break;JSONObject payload=AdminAccountSnapshot.bind(target,role==null?new JSONObject():json("role",role));Object response=api.adminRequest(role==null?"POST":"PATCH","/api/admin/web-accounts/"+UrlEncoding.form(qq)+(role==null?"/reset-temporary-password":""),payload);JSONObject success=response instanceof JSONObject?new JSONObject(response.toString()):new JSONObject();success.put("qq_id",qq).put("outcome","成功");items.put(success);}catch(Exception e){items.put(new JSONObject().put("qq_id",qq).put("outcome",FailureState.title(e)));if(e instanceof ApiClient.ApiException&&(((ApiClient.ApiException)e).status==401||((ApiClient.ApiException)e).status==403))break;}}return items;},true,result->{results=(JSONArray)result;selected.clear();renderAdmin();});}
    private void showResults(){LinearLayout b=card(body);b.addView(text("本次操作结果",20));b.addView(text("成功的临时密码仅保存在内存。导出不重复重设密码，离开此页或账号变化后清除。",13));for(int i=0;i<results.length();i++){JSONObject r=results.optJSONObject(i);TextView item=text(r.optString("qq_id")+" · "+r.optString("outcome")+(r.has("temporary_password")?"\n临时密码："+r.optString("temporary_password")+"\n有效期："+TrainingUi.date(r.optLong("expires_at")):""),14);item.setSaveEnabled(false);b.addView(item);}b.addView(button("导出 Excel / 系统分享",()->{if(!access())return;try{Intent send=AccountExportProvider.prepare(this,AccountWorkbook.create(results));opening=true;startActivity(Intent.createChooser(send,"导出本次成功结果"));}catch(Exception e){notice.show("导出",e);}}));b.addView(button("清除结果，返回账号列表",()->{results=new JSONArray();AccountExportProvider.clear(this);renderAdmin();}));}
}
